class Solution {
  public int fixedPanelsPositiveInkInvoice(int[] readings, int k) {
    int[] a=readings; List<Integer> out=new ArrayList<>();
    {int s=0;for(int i=0;i<a.length;i++){s+=a[i];if(i>=k)s-=a[i-k];if(i>=k-1)out.add(s);}}
    int answer=0;for(int x:out)if(x>0)answer+=x;return answer;
  }
}
